{
  "decision": "REVISE",
  "detail": {
    "days": 14,
    "checkpoint": "Both reports produced from the same shared loops/dictionaries foundation: a CSV totals report and a JSON totals report, each reading a small dataset and printing correct totals."
  },
  "tradeOffExplanation": "The shared loops/dictionaries prerequisite is owned once by plan_1 and consumed by plan_2 through a shared dependency, so its minutes are not duplicated. Both plans are small and bounded, so the next 14 days are detailed to the point where each report is produced; no later phases are invented because the accepted outcomes are fully covered by the detailed work.",
  "plans": [
    {
      "planRef": "plan_1",
      "blueprint": {
        "schemaVersion": 2,
        "strategy": {
          "policy": "ROADMAP",
          "outcome": "Prepare a CSV totals report using loops and dictionaries, with the shared loops/dictionaries prerequisite owned here.",
          "explanation": "The learner is new to loops and dictionaries, so the shared prerequisite is taught once here as a compact integrated activity that immediately feeds the CSV report. The CSV report is then built as a single authentic task. Because the outcome is small and bounded, the detailed work reaches the stopping point within 14 days and no later phases are needed.",
          "recommendedEffort": {
            "lowMinutes": 90,
            "likelyMinutes": 150,
            "highMinutes": 240
          },
          "phases": [
            {
              "localId": "foundation",
              "title": "Shared loops and dictionaries foundation",
              "outcome": "Use loops and dictionaries to read and total small datasets.",
              "effort": {
                "lowMinutes": 40,
                "likelyMinutes": 60,
                "highMinutes": 90
              },
              "readinessCriterion": "Can iterate a list of dictionaries and accumulate totals in a dictionary without step-by-step guidance."
            },
            {
              "localId": "csv_report",
              "title": "CSV totals report",
              "outcome": "Produce a CSV totals report from a small dataset.",
              "effort": {
                "lowMinutes": 50,
                "likelyMinutes": 90,
                "highMinutes": 150
              },
              "readinessCriterion": "The CSV report runs on a small dataset and prints correct totals."
            }
          ]
        },
        "scope": [
          {
            "scopeRef": "scope_1",
            "disposition": "INCLUDED",
            "contribution": "Owns the shared loops/dictionaries prerequisite once; plan_2 depends on this work rather than duplicating it."
          },
          {
            "scopeRef": "scope_2",
            "disposition": "INCLUDED",
            "contribution": "The CSV totals report is the concrete deliverable that applies the shared foundation."
          }
        ],
        "activities": [
          {
            "localId": "loops_dicts_foundation",
            "outcomeRefs": [
              "foundation"
            ],
            "scopeRefs": [
              "scope_1"
            ],
            "title": "Learn and apply loops and dictionaries on a small dataset",
            "activityType": "integrated learning and practice",
            "purpose": "Build the shared loops/dictionaries prerequisite once, with immediate application so it is usable for both reports.",
            "instructions": "Work with a small list of dictionaries (for example, 5-8 expense records with category and amount). Write a loop that iterates the list, and use a dictionary to accumulate a total per category. Run it, inspect the output, and adjust until the totals are correct. Then modify the data slightly and confirm the loop still produces correct totals. Keep the code you write; it will be reused for the CSV report.",
            "completionCriterion": "A runnable snippet that loops over a list of dictionaries and prints correct per-category totals, demonstrated on at least two different small datasets.",
            "effort": {
              "lowMinutes": 40,
              "likelyMinutes": 60,
              "highMinutes": 90
            },
            "timeboxMinutes": 60,
            "commitment": {
              "category": "COMMITTED"
            },
            "hardDependencies": [],
            "cognitiveDemand": "MODERATE"
          },
          {
            "localId": "csv_report_build",
            "outcomeRefs": [
              "csv_report"
            ],
            "scopeRefs": [
              "scope_2"
            ],
            "title": "Build the CSV totals report",
            "activityType": "authentic project task",
            "purpose": "Apply the shared loops/dictionaries foundation to produce the CSV totals report, which is the accepted outcome for this plan.",
            "instructions": "Using the loops and dictionary accumulation from the foundation activity, write a script that reads a small CSV of expenses (columns such as category and amount), computes totals per category, and writes or prints a CSV totals report. Run it on a small dataset, check the totals by hand for at least two categories, and fix any discrepancies. The report must be produced by the script, not typed manually.",
            "completionCriterion": "A script that reads a small CSV and outputs a CSV totals report with correct per-category totals, verified against a hand check.",
            "effort": {
              "lowMinutes": 50,
              "likelyMinutes": 90,
              "highMinutes": 150
            },
            "timeboxMinutes": 90,
            "commitment": {
              "category": "COMMITTED"
            },
            "hardDependencies": [
              "loops_dicts_foundation"
            ],
            "cognitiveDemand": "HEAVY"
          }
        ],
        "decisions": {
          "assumptions": [
            "The learner has basic Python syntax (variables, lists, functions) but is new to loops and dictionaries, as stated.",
            "A small CSV dataset can be created or supplied by the learner."
          ],
          "tradeOffs": [
            "The shared prerequisite is owned here and consumed by plan_2 via a shared dependency, so its minutes are counted once rather than duplicated across both plans."
          ],
          "unresolvedUncertainty": [
            "The learner's exact prior Python fluency is unknown; the foundation activity is sized to be sufficient for a beginner and can be extended if the first run reveals gaps."
          ],
          "stoppingConditions": [
            "Stop when the CSV totals report script runs on a small dataset and produces correct per-category totals verified by hand."
          ]
        }
      }
    },
    {
      "planRef": "plan_2",
      "blueprint": {
        "schemaVersion": 2,
        "strategy": {
          "policy": "ROADMAP",
          "outcome": "Build a JSON expenses report using the shared loops/dictionaries prerequisite owned by plan_1.",
          "explanation": "The loops/dictionaries prerequisite is not retaught here; it is consumed from plan_1 through a shared dependency. The JSON report is a single authentic task that applies that foundation to a different output format. Because the outcome is small and bounded, the detailed work reaches the stopping point within 14 days and no later phases are needed.",
          "recommendedEffort": {
            "lowMinutes": 50,
            "likelyMinutes": 90,
            "highMinutes": 150
          },
          "phases": [
            {
              "localId": "json_report",
              "title": "JSON expenses report",
              "outcome": "Produce a JSON expenses report with correct totals.",
              "effort": {
                "lowMinutes": 50,
                "likelyMinutes": 90,
                "highMinutes": 150
              },
              "readinessCriterion": "The JSON report runs on a small dataset and contains correct per-category totals."
            }
          ]
        },
        "scope": [
          {
            "scopeRef": "scope_1",
            "disposition": "INCLUDED",
            "contribution": "The shared loops/dictionaries prerequisite is required for the JSON report but is owned and taught by plan_1; this plan consumes it through a shared dependency and does not duplicate the work."
          },
          {
            "scopeRef": "scope_2",
            "disposition": "INCLUDED",
            "contribution": "The JSON expenses report is the concrete deliverable that applies the shared foundation to a JSON output."
          }
        ],
        "activities": [
          {
            "localId": "json_report_build",
            "outcomeRefs": [
              "json_report"
            ],
            "scopeRefs": [
              "scope_2"
            ],
            "title": "Build the JSON expenses report",
            "activityType": "authentic project task",
            "purpose": "Apply the shared loops/dictionaries foundation to produce the JSON expenses report, which is the accepted outcome for this plan.",
            "instructions": "Using the loops and dictionary accumulation you already built in the shared foundation, write a script that reads a small expenses dataset, computes totals per category, and outputs a JSON expenses report (for example, a dictionary of category totals serialized to JSON). Run it on a small dataset, check the totals by hand for at least two categories, and fix any discrepancies. The JSON must be produced by the script, not typed manually.",
            "completionCriterion": "A script that reads a small expenses dataset and outputs a JSON report with correct per-category totals, verified against a hand check.",
            "effort": {
              "lowMinutes": 50,
              "likelyMinutes": 90,
              "highMinutes": 150
            },
            "timeboxMinutes": 90,
            "commitment": {
              "category": "COMMITTED"
            },
            "hardDependencies": [],
            "cognitiveDemand": "HEAVY"
          }
        ],
        "decisions": {
          "assumptions": [
            "The learner will have completed the shared loops/dictionaries foundation in plan_1 before starting the JSON report.",
            "A small expenses dataset can be created or supplied by the learner."
          ],
          "tradeOffs": [
            "No separate loops/dictionaries relearning is booked here; the shared dependency carries that prerequisite so minutes are not duplicated."
          ],
          "unresolvedUncertainty": [
            "Whether the learner's foundation from plan_1 will be sufficient for JSON serialization specifically; the JSON report activity includes a hand check that will reveal any gap."
          ],
          "stoppingConditions": [
            "Stop when the JSON expenses report script runs on a small dataset and produces correct per-category totals verified by hand."
          ]
        }
      }
    }
  ],
  "sharedDependencies": [
    {
      "prerequisite": {
        "planRef": "plan_1",
        "activityId": "loops_dicts_foundation"
      },
      "dependent": {
        "planRef": "plan_2",
        "activityId": "json_report_build"
      },
      "strength": "HARD",
      "reason": "The JSON expenses report requires the loops/dictionaries foundation, which is owned and taught once by plan_1; plan_2 consumes it without duplicating the work."
    }
  ]
}
